1	/**
2	 * Scoped per testing.md: this organism's own contract (given a variation + props, does it render
3	 * the right children with the right flags, and does every interactive control still fire its own
4	 * callback) — not ZimmProductCardMedia/ZimmProductCardContent's own internal logic, which is
5	 * already proven in their own index.test.tsx files. Both are composed for real here (not mocked
6	 * out), the same "costs nothing, gives real integration confidence" precedent
7	 * zimmProductCardContent/index.test.tsx already documents for its own composed atoms/molecules.
8	 *
9	 * Only `useMultiStyleConfig` is mocked, with one flat object covering every part every composed
10	 * descendant reads (`ZimmProductCardMedia`, `ZimmSlideIndicator`, `ZimmProductCardContent`,
11	 * `ZimmProductPrice`, `ZimmSizeChipGroup`, `ZimmSizeChip`, and this organism's own `root`) — same
12	 * "neither test setup nor Chakra cares which recipe name asked for it" precedent
13	 * zimmProductCardMedia/index.test.tsx documents. `ZimmProductName`'s `useStyleConfig` call is left
14	 * real/unmocked, same as zimmProductCardContent/index.test.tsx.
15	 */
16	import React from 'react';
17	import { describe, test, expect, vi } from 'vitest';
18	import { render, screen } from '@testing-library/react';
19	import userEvent from '@testing-library/user-event';
20	import { IntlProvider } from 'react-intl';
21	import { MemoryRouter } from 'react-router-dom';
22	import { ZimmProductCard } from './index';
23	import type {
24	  ZimmProductCardProps,
25	  ZimmProductCardImage,
26	  ZimmProductCardBaseProps,
27	  ZimmProductCardPlpVariation,
28	  ZimmProductCardHomeVariation,
29	  ZimmProductCardWishlistVariation,
30	} from './index';
31	import { ZimmProductCard as ZimmProductCardRecipe } from './zimmProductCard.css';
32	
33	vi.mock('@chakra-ui/react', async (importOriginal) => {
34	  const actual = await importOriginal<typeof import('@chakra-ui/react')>();
35	  return {
36	    ...actual,
37	    useMultiStyleConfig: () => ({
38	      // This organism's own recipe.
39	      root: {},
40	      // ZimmProductCardMedia.
41	      scrollContainer: {},
42	      slide: {},
43	      image: {},
44	      hoverSwapBase: {},
45	      hoverSwapOverlay: {},
46	      close: {},
47	      carousel: {},
48	      arrowButton: {},
49	      indicatorWrapper: {},
50	      // ZimmSlideIndicator.
51	      dot: {},
52	      // ZimmProductCardContent.
53	      nameRow: {},
54	      nameLink: {},
55	      bagWrapper: {},
56	      bagButton: {},
57	      attributesRow: {},
58	      colourText: {},
59	      sizeText: {},
60	      priceWrapper: {},
61	      sizeChipWrapper: {},
62	      notifyMeButton: {},
63	      // ZimmProductPrice.
64	      container: {},
65	      wasPrice: {},
66	      nowPrice: {},
67	      // ZimmSizeChipGroup.
68	      radiogroup: {},
69	      oneSize: {},
70	      // ZimmSizeChip.
71	      chip: {},
72	    }),
73	  };
74	});
75	
76	// ZimmIcon (used by ZimmProductCardContent's bag button) and the icons barrel (used by
77	// ZimmProductCardMedia's close/arrow buttons): known Vitest SVG side-effect issue documented in
78	// .claude/rules/testing.md's "Known gap: ZimmIcon throws under Vitest". Mocked at the same
79	// resolved module each consumer imports — both consumers sit at the same depth below `ui-kits/`
80	// as this test file, so the relative specifiers are identical to what
81	// zimmProductCardContent/index.test.tsx and zimmProductCardMedia/index.test.tsx use themselves.
82	vi.mock('../../atoms/zimmIcon', () => ({ ZimmIcon: () => null }));
83	vi.mock('../../../icons', () => ({
84	  ChevronLeftIcon: () => null,
85	  ChevronRightIcon: () => null,
86	  CloseIcon: () => null,
87	}));
88	
89	const wrap = (ui: React.ReactElement) =>
90	  render(
91	    <MemoryRouter>
92	      <IntlProvider locale="en" defaultLocale="en">
93	        {ui}
94	      </IntlProvider>
95	    </MemoryRouter>,
96	  );
97	
98	const PRIMARY: ZimmProductCardImage = { src: 'primary.jpg', alt: 'Zimmermann dress, front' };
99	const GALLERY: ZimmProductCardImage[] = [
100	  { src: 'g1.jpg', alt: 'Zimmermann dress, front' },
101	  { src: 'g2.jpg', alt: 'Zimmermann dress, side' },
102	  { src: 'g3.jpg', alt: 'Zimmermann dress, back' },
103	];
104	
105	const SIZES = [
106	  { value: 'xs', label: 'XS' },
107	  { value: 's', label: 'S' },
108	];
109	
110	/** Mocks the scroll container's native `scrollTo` (absent under jsdom), same technique as
111	 *  zimmProductCardMedia/index.test.tsx's own mockScrollTo. */
112	const mockScrollTo = (): ReturnType<typeof vi.fn> => {
113	  const scrollContainer = screen.getByTestId('card-media-scroll');
114	  const scrollTo = vi.fn();
115	  scrollContainer.scrollTo = scrollTo;
116	  return scrollTo;
117	};
118	
119	/**
120	 * A complete, valid props object for a given variation — narrows on `variation` with a plain
121	 * `switch` (fine here: the "no switch/if on props.variation" constraint applies only to
122	 * index.tsx's own render body, not to test fixtures).
123	 *
124	 * Overloaded (not a single `(variation) => ZimmProductCardProps` signature) so a call site that
125	 * passes a literal (`buildCardProps('plp')`) gets back the properly *narrow* per-variation type,
126	 * not the full union — needed so a test can then add a variation-specific prop on top (e.g.
127	 * `{...buildCardProps('wishlist')} onRemove={fn}`) without TypeScript rejecting it as "not
128	 * present on every union member." A `test.each` call site passing a runtime (non-literal)
129	 * `variation` still resolves to the final, general overload below.
130	 */
131	function buildCardProps(variation: 'plp'): ZimmProductCardBaseProps & ZimmProductCardPlpVariation;
132	function buildCardProps(variation: 'home'): ZimmProductCardBaseProps & ZimmProductCardHomeVariation;
133	function buildCardProps(variation: 'wishlist'): ZimmProductCardBaseProps & ZimmProductCardWishlistVariation;
134	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps;
135	function buildCardProps(variation: ZimmProductCardProps['variation']): ZimmProductCardProps {
136	  const base = {
137	    id: 'p1',
138	    href: '/product/1',
139	    name: 'Natura Dress',
140	    headingLevel: 'h3' as const,
141	    primaryImage: PRIMARY,
142	  };
143	  switch (variation) {
144	    case 'wishlist':
145	      return { ...base, variation, colour: 'Ivory', size: 'M', onRemove: vi.fn() };
146	    case 'home':
147	      return { ...base, variation };
148	    case 'plp':
149	      return { ...base, variation };
150	    default:
151	      // Exhaustiveness guard — a new union member without a matching branch here fails `tsc`,
152	      // not silently falls through to a wrong variation's shape.
153	      return ((): never => {
154	        throw new Error(`buildCardProps: unhandled variation ${JSON.stringify(variation)}`);
155	      })();
156	  }
157	}
158	
159	describe('ZimmProductCardProps — discriminated union is enforced at compile time', () => {
160	  // Both cases below are type-only proof: `@ts-expect-error` makes `tsc --noEmit` fail this file
161	  // if the offending line does NOT produce a compile error (an "Unused '@ts-expect-error'
162	  // directive" diagnostic) — so these only stay green while the union genuinely rejects the
163	  // invalid shape. The runtime assertion is trivial; TypeScript strips the annotation either way,
164	  // so the object still constructs and runs at test time regardless of what `tsc` says about it.
165	  test('wishlist variation requires onRemove, colour and size (type-only)', () => {
166	    // @ts-expect-error — wishlist requires onRemove, colour and size; none are supplied here.
167	    const invalid: ZimmProductCardProps = {
168	      id: 'p1',
169	      href: '/product/1',
170	      name: 'Dress',
171	      headingLevel: 'h3',
172	      primaryImage: PRIMARY,
173	      variation: 'wishlist',
174	    };
175	    expect(invalid).toBeDefined();
176	  });
177	
178	  test('home variation does not accept onRemove (type-only)', () => {
179	    // Assigned to the narrow per-variation intersection, not the `ZimmProductCardProps` union
180	    // alias: TypeScript's excess-property check on a *union* target only flags a property as
181	    // excess when it is unknown to EVERY member, so `onRemove` (valid on the wishlist member)
182	    // would silently pass here even under `variation: 'home'` if assigned to the union type
183	    // directly — confirmed empirically while building this test (an earlier version of this
184	    // exact case, assigned to `ZimmProductCardProps`, produced an "unused @ts-expect-error"
185	    // compile error because of this). The narrow intersection has no such escape hatch: it is a
186	    // plain object type with no `onRemove` key anywhere, so the excess property is genuinely
187	    // unknown and TypeScript reports it.
188	    //
189	    // The directive sits directly above the `onRemove` line, not the `const invalid = {` line
190	    // above it: TS anchors this specific "object literal may only specify known properties"
191	    // diagnostic to the offending property's own line, and `@ts-expect-error` only suppresses
192	    // (and only counts as "used" for) a diagnostic reported on the *immediate next* line.
193	    const invalid: ZimmProductCardBaseProps & ZimmProductCardHomeVariation = {
194	      id: 'p2',
195	      href: '/product/1',
196	      name: 'Dress',
197	      headingLevel: 'h3',
198	      primaryImage: PRIMARY,
199	      variation: 'home',
200	      // @ts-expect-error — onRemove does not exist on the home variation's own shape.
201	      onRemove: () => {},
202	    };
203	    expect(invalid).toBeDefined();
204	  });
205	});
206	
207	describe('ZimmProductCard — AC1: primary image renders for every variation x availability', () => {
208	  const cases: Array<[ZimmProductCardProps['variation'], boolean]> = [
209	    ['plp', false],
210	    ['plp', true],
211	    ['home', false],
212	    ['home', true],
213	    ['wishlist', false],
214	    ['wishlist', true],
215	  ];
216	
